() => {
  // Click the XAI provider row in the providers table
  const rows = [...document.querySelectorAll("tr")];
  const row = rows.find(r => /\bXAI\b/.test(r.textContent) && /grok/i.test(r.textContent));
  if (row) { row.click(); }
  return { clicked: !!row, rowText: row ? row.textContent.replace(/\s+/g,' ').trim() : null };
}

() => {
  const rows = [...document.querySelectorAll("tr")].map(r => r.textContent.replace(/\s+/g,' ').trim()).filter(Boolean);
  return { count: rows.length, rows };
}

() => {
  const rows = [...document.querySelectorAll("tr")];
  const row = rows.find(r => /grok-voice-latest/.test(r.textContent));
  if (row) row.click();
  return { clicked: !!row };
}

() => {
  const click = (text) => {
    const el = [...document.querySelectorAll("button, a, [class*='nav']")].find(e => e.textContent.trim().toUpperCase().includes(text));
    if (el) { el.click(); return true; }
    return false;
  };
  return { toCall: click("SESSIONS") };
}

() => {
  const btn = document.querySelector(".tb-btn-primary") || [...document.querySelectorAll("button")].find(b => /tb-btn-primary|danger/.test(b.className));
  if (btn) btn.click();
  return { clicked: !!btn, cls: btn ? btn.className : null };
}

async () => {
  await new Promise(r => setTimeout(r, 1200)); // allow token fetch + fail
  const cap = document.querySelector(".tb-caption-t, [class*='caption']");
  const state = [...document.querySelectorAll("[class*='call-state'], [class*='state']")].map(e=>e.textContent.trim()).filter(Boolean);
  return { caption: cap ? cap.textContent.trim() : null, states: state.slice(0,4) };
}

