78	  const endedRef = useRef(false);
79	  const configuredRef = useRef(false);
80	  const inputRmsRef = useRef(0);
81	  const turnSeqRef = useRef(0);
82	  const agentTurnIdRef = useRef<string | null>(null);
83	  const agentBufRef = useRef("");
84	  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
