88	  const personaRef = useRef(persona);
89	  personaRef.current = persona;
90	
91	  const teardown = useCallback(() => {
92	    if (interruptTimerRef.current) {
93	      clearTimeout(interruptTimerRef.current);
94	      interruptTimerRef.current = null;
95	    }
96	    if (procRef.current) {
97	      procRef.current.onaudioprocess = null;
98	      procRef.current.disconnect();
99	      procRef.current = null;
100	    }
101	    if (sourceRef.current) {
102	      sourceRef.current.disconnect();
103	      sourceRef.current = null;
104	    }
105	    if (streamRef.current) {
106	      streamRef.current.getTracks().forEach((t) => t.stop());
107	      streamRef.current = null;
108	    }
109	    if (playbackRef.current) {
110	      playbackRef.current.stop();
111	      playbackRef.current = null;
112	    }
113	    if (wsRef.current) {
114	      try {
115	        wsRef.current.close();
116	      } catch {
117	        // already closing
118	      }
119	      wsRef.current = null;
120	    }
121	    if (ctxRef.current) {
122	      void ctxRef.current.close();
123	      ctxRef.current = null;
124	    }
125	    configuredRef.current = false;
126	    agentTurnIdRef.current = null;
127	    agentBufRef.current = "";
128	    inputRmsRef.current = 0;
129	  }, []);
130	
131	  const send = useCallback((obj: unknown) => {
132	    const ws = wsRef.current;
133	    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
134	  }, []);
135	
136	  const start = useCallback(() => {
137	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
138	    endedRef.current = false;
139	    configuredRef.current = false;
140	    setTurns([]);
141	    setCallState("connecting");
142	    setCaption("establishing session…");
143	
144	    const fail = (msg: string) => {
145	      endedRef.current = true;
146	      teardown();
147	      setCallState("ended");
148	      setCaption(msg);
149	    };
150	
151	    void (async () => {
152	      // 1) Mint the ephemeral client-secret server-side.
153	      let token: string | null = null;
154	      try {
155	        const res = await fetch("/api/xai/token", { method: "POST" });
156	        const data = await res.json();
157	        if (!res.ok) {
158	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
159	          return;
160	        }
161	        token = extractToken(data);
162	      } catch {
163	        fail("— could not reach token endpoint —");
164	        return;
165	      }
166	      if (!token) {
167	        fail("— no xAI token returned —");
168	        return;
169	      }
170	      if (endedRef.current) return; // hung up during fetch
171	
172	      // 2) Audio context (native rate, advertised to xAI so no resampling).
173	      const ctx = new AudioContext();
174	      ctxRef.current = ctx;
175	      const rate = ctx.sampleRate;
176	      playbackRef.current = new PlaybackQueue(ctx);
177	
178	      // Local mutable capture buffers (live as long as the processor node).
179	      let pending: Float32Array[] = [];
180	      let total = 0;
181	      const chunkSize = Math.floor((rate * CHUNK_MS) / 1000);
182	
183	      const startCapture = async () => {
184	        try {
185	          const stream = await navigator.mediaDevices.getUserMedia({
186	            audio: {
187	              channelCount: 1,
188	              echoCancellation: true,
189	              noiseSuppression: true,
190	              autoGainControl: true,
191	            },
192	          });
193	          streamRef.current = stream;
194	          if (ctx.state === "suspended") await ctx.resume();
195	          const source = ctx.createMediaStreamSource(stream);
196	          sourceRef.current = source;
197	          const proc = ctx.createScriptProcessor(4096, 1, 1);
198	          procRef.current = proc;
199	          proc.onaudioprocess = (e) => {
200	            const input = e.inputBuffer.getChannelData(0);
201	            inputRmsRef.current = mutedRef.current ? 0 : calculateRms(input);
202	            if (mutedRef.current) return;
203	            pending.push(new Float32Array(input));
204	            total += input.length;
205	            while (total >= chunkSize) {
206	              const chunk = new Float32Array(chunkSize);
207	              let offset = 0;
208	              while (offset < chunkSize && pending.length > 0) {
209	                const buf = pending[0];
210	                const need = chunkSize - offset;
211	                if (buf.length <= need) {
212	                  chunk.set(buf, offset);
213	                  offset += buf.length;
214	                  total -= buf.length;
215	                  pending.shift();
216	                } else {
217	                  chunk.set(buf.subarray(0, need), offset);
218	                  pending[0] = buf.subarray(need);
219	                  offset += need;
220	                  total -= need;
221	                }
222	              }
223	              send({ type: "input_audio_buffer.append", audio: float32ToPcm16Base64(chunk) });
224	            }
225	          };
