        console.log(`[${callId}] FUNCTION RESULT: ${result}`);

        // Send the function result back to XAI
        const functionResult = {
          type: 'conversation.item.create',
          item: {
            type: 'function_call_output',
            call_id: callId_fn,
            output: result,
          }
