() => {
  const els = [...document.querySelectorAll('button, a, [role="tab"], li, span')];
  const target = els.find(e => /personas/i.test(e.textContent || "") && e.offsetParent !== null && (e.textContent||"").length < 30);
  if (target) { target.click(); return "clicked: " + target.tagName + " / " + target.textContent.trim(); }
  return "nav not found; candidates: " + els.filter(e=>/persona/i.test(e.textContent||"")).slice(0,5).map(e=>e.tagName+":"+(e.textContent||"").trim().slice(0,20)).join(" | ");
}

() => {
  const cards = [...document.querySelectorAll('.tb-persona-card')];
  const onyx = cards.find(c => /ONYX/.test(c.textContent||""));
  if (onyx) onyx.click();
  return "clicked ONYX";
}

() => {
  const cards = [...document.querySelectorAll('.tb-persona-card')];
  return cards.filter(c=>c.querySelector('.tb-persona-dot')).map(c => {
    const name = (c.querySelector('.tb-persona-name')||{}).textContent;
    const dot = c.querySelector('.tb-persona-dot');
    const cs = getComputedStyle(dot);
    return { name, bg: cs.backgroundColor, glow: cs.boxShadow !== 'none' };
  });
}

() => {
  const els = [...document.querySelectorAll('button, a, [role="tab"]')];
  const t = els.find(e => /^settings/i.test((e.textContent||"").trim()) && e.offsetParent !== null);
  if (t) { t.click(); return "clicked settings"; }
  return "not found";
}

() => {
  const sel = document.querySelector('.tb-select');
  if (!sel) return "no select";
  return { selected: sel.value, options: [...sel.options].map(o => o.textContent) };
}

